const f = $input.first().json;
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };

const name   = String(f['Your Name'] || 'Friend').trim();
const habit  = String(f['Habit Name'] || 'your habit').trim();
const status = f['Habit Status Today'] || 'Done';
const streak = num(f['Current Streak (days)']);
const missed = num(f['Days Missed in a Row']);
const wType  = f['Workout Type'] || 'None';
const wMin   = num(f['Workout Duration (min)']);
const wInt   = f['Workout Intensity'] || 'Low';
const hiRun  = num(f['Recent High-Intensity Workouts in a Row']);
const steps  = num(f['Steps Today']);
const water  = num(f['Water (ml)']);
const sleep  = num(f['Sleep (hours)']);
const mood   = f['Mood'] || 'Okay';
const goal   = String(f['Goal Title'] || '').trim();
const goalPct = num(f['Goal Progress (%)']);
const notes  = String(f['Notes'] || '').trim();

// ---- Validation (TC-08: negative values rejected) ----
const errors = [];
if (wMin < 0) errors.push('Workout duration cannot be negative.');
if (steps < 0) errors.push('Steps cannot be negative.');
if (water < 0) errors.push('Water intake cannot be negative.');
if (sleep < 0 || sleep > 24) errors.push('Sleep hours must be between 0 and 24.');
if (goalPct < 0 || goalPct > 100) errors.push('Goal progress must be between 0 and 100.');
if (streak < 0 || missed < 0) errors.push('Streak and missed days cannot be negative.');

// ---- Rule-based coaching layer (from HabitPulse section 10) ----
let ruleMessage, ruleTag;
if (missed >= 3) {
  ruleTag = 'Restart small';
  ruleMessage = "It's been a few days, and that's okay. Let's restart small: try just 5 minutes of " + habit + " today.";
} else if (missed >= 1 || status === 'Missed') {
  ruleTag = 'Gentle reminder';
  ruleMessage = 'You missed a day. No problem. Get back on track today with a small step on ' + habit + '.';
} else if (streak > 0 && streak % 7 === 0) {
  ruleTag = 'Milestone';
  ruleMessage = streak + '-day streak! Fantastic consistency.';
} else if (status === 'Partially Done') {
  ruleTag = 'Progress counts';
  ruleMessage = 'Partial effort still counts. Showing up matters more than perfection.';
} else {
  ruleTag = 'Momentum';
  ruleMessage = 'Nice work today. Keep the momentum going.';
}

const extras = [];
if (hiRun >= 3) extras.push('Rest day suggested: you have done several high-intensity workouts in a row.');
if (goal && goalPct >= 100) extras.push('Goal complete: "' + goal + '" is at 100%. Celebrate this win!');
else if (goal && goalPct >= 50) extras.push('Halfway there: "' + goal + '" is past 50%.');
if (sleep > 0 && sleep < 6) extras.push('Short on sleep? Aim for a little more rest tonight.');

const sessionId = name.toLowerCase().replace(/[^a-z0-9]+/g, '-') || 'user';

const prompt = 'Daily check-in from ' + name + ':\n'
  + '- Habit: ' + habit + ' | Status today: ' + status + '\n'
  + '- Current streak: ' + streak + ' days | Days missed in a row: ' + missed + '\n'
  + '- Workout: ' + wType + ', ' + wMin + ' min, intensity ' + wInt + ' | High-intensity workouts in a row: ' + hiRun + '\n'
  + '- Steps: ' + steps + ' | Water: ' + water + ' ml | Sleep: ' + sleep + ' h | Mood: ' + mood + '\n'
  + '- Goal: ' + (goal || 'none set') + ' (' + goalPct + '% complete)\n'
  + '- Notes: ' + (notes || 'none') + '\n'
  + '- Rule engine says: [' + ruleTag + '] ' + ruleMessage + ' ' + extras.join(' ');

return [{ json: {
  valid: errors.length === 0, errors,
  name, habit, status, streak, missed, wType, wMin, wInt, hiRun,
  steps, water, sleep, mood, goal, goalPct, notes,
  ruleMessage, ruleTag, extras, sessionId, prompt
}}];

const b = $('Rule-Based Coach').first().json;
const esc = s => String(s === undefined || s === null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const wrap = inner => '<div style="font-family:Segoe UI,Arial,sans-serif;max-width:640px;margin:auto;text-align:left;color:#1f2937;">' + inner + '</div>';

// ---- Invalid input branch ----
if (!b.valid) {
  const items = b.errors.map(e => '<li>' + esc(e) + '</li>').join('');
  return [{ json: { html: wrap(
    '<div style="background:#fef2f2;border-left:5px solid #dc2626;padding:14px;border-radius:8px;">'
    + '<b>Please fix your check-in and submit again:</b><ul>' + items + '</ul></div>'
  )}}];
}

// ---- Coaching text: AI output with rule-based fallback ----
let ai = String($json.output || '').replace(/\*\*/g, '').trim();
let source = 'Groq AI coach + HabitPulse rule engine (with memory)';
if (!ai) { ai = 'Coach Message: ' + b.ruleMessage; source = 'Rule-based fallback (AI unavailable)'; }

const aiHtml = ai.split('\n').filter(l => l.trim()).map(l => {
  const m = l.match(/^(Coach Message|Today's Tiny Action|Trend Note)\s*:\s*(.*)$/i);
  return m ? '<p style="margin:10px 0;"><b style="color:#4f46e5;">' + esc(m[1]) + ':</b> ' + esc(m[2]) + '</p>'
           : '<p style="margin:10px 0;">' + esc(l) + '</p>';
}).join('');

const chip = (label, value) =>
  '<div style="flex:1 1 140px;background:#f3f4f6;border-radius:10px;padding:10px;">'
  + '<div style="font-size:12px;color:#6b7280;">' + label + '</div>'
  + '<div style="font-size:18px;font-weight:600;">' + esc(value) + '</div></div>';

const extrasHtml = b.extras.length
  ? '<div style="background:#fffbeb;border-left:5px solid #f59e0b;padding:12px;border-radius:8px;margin:14px 0;">'
    + b.extras.map(e => '<div>&#9889; ' + esc(e) + '</div>').join('') + '</div>'
  : '';

const goalBar = b.goal
  ? '<div style="margin:14px 0;"><div style="font-size:13px;">Goal: <b>' + esc(b.goal) + '</b> (' + b.goalPct + '%)</div>'
    + '<div style="background:#e5e7eb;border-radius:8px;height:12px;overflow:hidden;">'
    + '<div style="width:' + Math.min(100, b.goalPct) + '%;background:#10b981;height:12px;"></div></div></div>'
  : '';

const html = wrap(
  '<h2 style="margin:0 0 4px;">Hi ' + esc(b.name) + '! &#127939;</h2>'
  + '<div style="display:inline-block;background:#4f46e5;color:#fff;padding:3px 12px;border-radius:20px;font-size:13px;">' + esc(b.ruleTag) + '</div>'
  + '<div style="display:flex;flex-wrap:wrap;gap:10px;margin:16px 0;">'
  + chip('Habit', b.habit + ' (' + b.status + ')')
  + chip('Streak', b.streak + ' days')
  + chip('Days missed', b.missed)
  + chip('Workout', b.wType + ' ' + b.wMin + ' min')
  + chip('Steps', b.steps)
  + chip('Water', b.water + ' ml')
  + chip('Sleep', b.sleep + ' h')
  + chip('Mood', b.mood)
  + '</div>'
  + goalBar
  + '<div style="background:#eef2ff;border-radius:10px;padding:14px;">' + aiHtml + '</div>'
  + extrasHtml
  + '<p style="font-size:12px;color:#6b7280;margin-top:16px;">Source: ' + esc(source) + '<br>'
  + 'HabitPulse gives general wellness guidance only, not medical advice. Please consult a professional for health concerns.</p>'
  + '<p style="font-size:13px;">Want to check in again? Reload this form page and submit a new check-in.</p>'
);

return [{ json: { html } }];
